head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getPopupWindowList]<br/>현재 Scope 와 동일한 Scope 를 가진 팝업의 Window 객체를 배열로 반환합니다.",
    "validation" : [
        "useFrameModal(선택) 파라미터를 true 로 설정하면 frameModal 속성이 있는 팝업만 반환해야 합니다.",
        "useFrameModal(선택) 파라미터를 false 로 설정하면 조건 없이 반환해야 합니다.",
        "scope(선택) 파라미터로 팝업 화면을 가져올 Scope 를 설정할 수 있어야 합니다.",
        "scope(선택) 파라미터 생략 시 호출한 화면의 Scope 가 자동으로 적용되어야 합니다.",
        "useMain(선택) 파라미터를 true 로 설정하면 $p.main() 결과를 반환해야 합니다.",
        "useMain(선택) 파라미터를 false 로 설정하면 Window 객체를 그대로 반환해야 합니다.",
        "해당하는 팝업이 없으면 빈 배열([])을 반환해야 합니다.",
    ]
}



scwin.wfSubScopeUuid = "";

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // WFrame 의 scope uuid 를 동적으로 조회
    var keys = Object.keys(WebSquare.idCache);
    for (var i = 0; i < keys.length; i++) {
        if (WebSquare.idCache[keys[i]].id === "mf_wf_sub") {
            scwin.wfSubScopeUuid = keys[i];
            break;
        }
    }
};



scwin.btn_openAllPopups_onclick = function () {
    // 1. 메인 scope 일반 팝업
    window.$p.openPopup("/sample/common_link/util_createPopup_1.xml", {
        id: "popup_main",
        type: "iframePopup",
        width: "300px",
        height: "200px",
        top: "100px",
        left: "100px",
        popupName: "popup_main (일반)",
        modal: false
    });

    // 2. 메인 scope frameModal 팝업
    window.$p.openPopup("/sample/common_link/util_createPopup_1.xml", {
        id: "popup_frameModal",
        type: "iframePopup",
        width: "300px",
        height: "200px",
        top: "100px",
        left: "400px",
        popupName: "popup_frameModal",
        modal: false,
        frameModal: "top"
    });

    // 3. WFrame scope 팝업
    wf_sub.getObj("scwin").openPopupInWFrame();

    wf_body_bottom.getObj("scwin").setReturnValue("팝업 3개 생성 완료");
    wf_body_bottom.getObj("scwin").setReturnValue("  popup_main (일반), popup_frameModal (frameModal), popup_wframe (WFrame scope)");
}



scwin.btn_getPopupWindowList_onclick = function () {
    var scope = par_scope.getValue();
    var useFrameModal = par_useFrameModal.getValue();
    var useMain = par_useMain.getValue();

    var scopeVal;
    if (scope === "omit") {
        scopeVal = undefined;
    } else if (scope === "wf_sub") {
        scopeVal = scwin.wfSubScopeUuid;
    } else {
        scopeVal = scope;
    }

    var useFrameModalVal = (useFrameModal !== "omit") ? (useFrameModal === "true") : undefined;
    var useMainVal = (useMain !== "omit") ? (useMain === "true") : undefined;

    var popWinList = window.$p.getPopupWindowList(useFrameModalVal, scopeVal, useMainVal);

    var scopeDisplay = (scope === "wf_sub") ? "'wf_sub'" : "undefined";
    wf_body_bottom.getObj("scwin").setReturnValue("getPopupWindowList(" + (useFrameModalVal !== undefined ? useFrameModalVal : "undefined") + ", " + scopeDisplay + ", " + (useMainVal !== undefined ? useMainVal : "undefined") + ")");
    wf_body_bottom.getObj("scwin").setReturnValue("배열 길이 : " + popWinList.length);

    if (popWinList.length > 0) {
        for (var i = 0; i < popWinList.length; i++) {
            var win = popWinList[i];
            var constructorName = win ? win.constructor.name : "null";
            var hasDocument = (win && win.document !== undefined);
            wf_body_bottom.getObj("scwin").setReturnValue("  [" + i + "] constructor: " + constructorName + ", document: " + hasDocument);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("해당 팝업 없음 (빈 배열)");
    }
}



scwin.btn_closeAll_onclick = function () {
    var popList = window.$p.getAllPopupList();
    for (var i = popList.length - 1; i >= 0; i--) {
        window.$p.closePopup(popList[i].id);
    }

    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("전체 닫기 완료");
    }, 500);
}
